var url = source.key,
html = java.ajax(url);
a = org.jsoup.Jsoup.parse(html)
.select(".nav li:gt(0):lt(11) a");
var arr = [], sort = [];
if(html && a){
	arr = Array.from(a, x => {
		txt = x.text(),href = String(x.attr("href"));
		url = /_1/.test(href) ? href
		.replace(/_1/,"_{{page}}") : 
		href.replace(/1/, "{{page}}");
		if(!/1|html?$/g.test(url) ) url += "<,{{page}}.html>";
			return [txt, url] });
		sort = arr.map(([title, link]) => ({
    "title": title,
    "url": link,
    "style": {
      "layout_flexGrow": 1,
       "layout_flexBasisPercent": 0.2
    }
  }) );

  JSON.stringify(sort);

	}else java.toast("发现列表获取失败！");

jsLib:
let replaceCover = (u) => {
    if (u.startsWith("https://")) u = u.substring(8)
    else u = u.substring(7)
    let uArr = u.split("/")
    uArr[0] = "https://p6-novel.byteimg.com/origin"
    let uArr2 = []
    uArr.forEach((x) => {
        if (!x.includes("?") && !x.includes("~")) uArr2.push(x)
        else uArr2.push(x.split("~")[0])
    })
    u = uArr2.join("/")
    return u
}

